DBUtils 核心类QueryRunnerorg.apache.commons.dbutils.QueryRunner类是 DBUtils 库中的中心类。 
它执行带有可插入策略的 SQL 查询来处理ResultSets。 这个类是线程安全的。
AsyncQueryRunnerorg.apache.commons.dbutils.AsyncQueryRunner类有助于执行具有异步支持的长时间运行的 SQL 查询。 这个类是线程安全的。 
该类支持与QueryRunner相同的方法，但它返回Callable对象，在之后可以使用它来检索结果。
ResultSetHandlerorg.apache.commons.dbutils.ResultSetHandler接口负责将 ResultSets 转换为对象。
BeanHandlerorg.apache.commons.dbutils.BeanHandler是ResultSetHandler接口的实现，负责将第一个ResultSet行转换为JavaBean。 这个类是线程安全的。
BeanListHandlerorg.apache.commons.dbutils.BeanListHandler是ResultSetHandler接口的实现，负责将ResultSet行转换为 Java Bean 列表。 这个类是线程安全的。
ArrayListHandlerorg.apache.commons.dbutils.ArrayListHandler是ResultSetHandler接口的实现，负责将ResultSet行转换为object[]。 这个类是线程安全的。
MapListHandlerorg.apache.commons.dbutils.MapListHandler是ResultSetHandler接口的实现，负责将ResultSet行转换为 Maps 列表。 这个类是线程安全的。
自定义 DBUtils自定义处理程序可以通过实现ResultSetHandler接口或扩展任何现有的ResultSetHandler实现来创建自己的自定义处理程序。
在下面的示例中，我们通过扩展BeanHandler类创建了自定义处理程序EmployeeHandler。
EmployeeHandler.java
import java.sql.ResultSet;
import java.sql.SQLException;

import org.apache.commons.dbutils.handlers.BeanHandler;

public class EmployeeHandler extends BeanHandler&lt;Employee&gt; {

	public EmployeeHandler() {
		super(Employee.class);
	}

	@Override
	public Employee handle(ResultSet rs) throws SQLException {
		Employee employee = super.handle(rs);
		employee.setName(employee.getFirst() + ", " + employee.getLast());
		return employee;
	}
}

MyHandlerMain.java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;

import org.apache.commons.dbutils.DbUtils;
import org.apache.commons.dbutils.QueryRunner;

public class MyHandlerMain {
	static final String DB_URL = "jdbc:mysql://localhost:3306/test?serverTimezone=UTC";
	static final String USER = "user";
	static final String PASS = "password";

	public static void main(String[] args) throws SQLException {
		Connection conn = null;
		QueryRunner queryRunner = new QueryRunner();
		conn = DriverManager.getConnection(DB_URL, USER, PASS);
		EmployeeHandler employeeHandler = new EmployeeHandler();

		try {
			Employee emp = queryRunner.query(conn, "SELECT * FROM employees WHERE first=?", employeeHandler, "Sumit");
			System.out.print("ID: " + emp.getId() + ", Age: " + emp.getAge() + ", Name: " + emp.getName());
		} finally {
			DbUtils.close(conn);
		}
	}
}

自定义行处理器如果数据库表中的列名和等价的 javabean 对象名称不相似，那么我们可以通过使用自定义的BasicRowProcessor对象来映射它们。
EmployeeHandler2.java
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.HashMap;
import java.util.Map;

import org.apache.commons.dbutils.BasicRowProcessor;
import org.apache.commons.dbutils.BeanProcessor;
import org.apache.commons.dbutils.handlers.BeanHandler;

public class EmployeeHandler2 extends BeanHandler&lt;Employee&gt; {

   public EmployeeHandler2() {
      super(Employee.class, new BasicRowProcessor(new BeanProcessor(mapColumnsToFields())));
   }

   @Override
   public Employee handle(ResultSet rs) throws SQLException {
      Employee employee = super.handle(rs);
      employee.setName(employee.getFirst() +", " + employee.getLast());
      return employee;
   }

   public static Map&lt;String, String&gt; mapColumnsToFields() {
      Map&lt;String, String&gt; columnsToFieldsMap = new HashMap&lt;&gt;();
      columnsToFieldsMap.put("ID", "id");
      columnsToFieldsMap.put("AGE", "age");        
      return columnsToFieldsMap;
   }
}

