// 创建一个序列 (a,b) = { x | a &lt; x &lt; b}
Range&lt;Integer&gt; range2 = Range.open(0, 9); // 1 2 3 4 5 6 7 8

// 创建一个序列 (a,b] = { x | a &lt; x &lt;= b}
Range&lt;Integer&gt; range3 = Range.openClosed(0, 9); // 1 2 3 4 5 6 7 8 9

// 创建一个序列 [a,b) = { x | a &lt;= x &lt; b}
