@ApiModel 的用途有 2 个：

当请求数据描述，即 @RequestBody 时， 用于封装请求（包括数据的各种校验）数据；
当响应值是对象时，即 @ResponseBody 时，用于返回值对象的描述。

@ApiModelProperty@ApiModelProperty：用在 JavaBean 类的属性上面，说明属性的含义
Swagger 示例API 基本信息配置类要想使用 Swagger，必须编写一个配置类来配置 Swagger，这里的配置类如下：
@Configuration
@EnableSwagger2
public class SwaggerConfig {

    @Bean
    public Docket docket(){
        // 构造函数传入初始化规范，这是swagger2规范
        return new Docket(DocumentationType.SWAGGER_2)
                .apiInfo(apiInfo()) //apiInfo： 添加api详情信息，参数为ApiInfo类型的参数
                .groupName("System") // 配置分组
                .enable(true) // 配置是否启用Swagger，如果是false，在浏览器将无法访问，默认是true
                .select()
                .apis(RequestHandlerSelectors.basePackage("com.system.controller")) //apis： 添加过滤条件,
                .paths(PathSelectors.any()) //paths： 这里是控制哪些路径的api会被显示出来
                .build().pathMapping("/"); 
    }
    public ApiInfo apiInfo(){
        Contact contact=new Contact("xiaojue","http://localhost:8181","hellojue@foxmail.com");
        return new ApiInfoBuilder()
                .contact(contact)
                .title("API文档")
                .description("系统API文档")
                .termsOfServiceUrl("")
                .version("1.0")
                .build();
    }
}

