private int[] nums = {2,4,6,8,10,12,14,16,18};

查找指定值public int equalVal(int[] nums, int target) {
    int low = 0, high = nums.length - 1;
    while (low &lt;= high) {
        int mid = (low + high) / 2;
        if (nums[mid] == target) {
            return nums[mid];
        } else if (nums[mid] &gt; target) {//查找左边的
            high = mid - 1;
        } else {//查找右边的
            low = mid + 1;
        }
    }
    return -1;
}

