function strip(html) {
   var tmp = document.createElement("div");
   tmp.innerHTML = html;
   var ulInfo = tmp.getElementsByTagName('ul');
   if(ulInfo!=null &amp;&amp; ulInfo.length&gt;0){
      ulInfo[0].remove();
   }
   return tmp.textContent.trim() || tmp.innerText.trim() || "";
}

