定义一个 HttpGet 实体类import org.apache.http.client.methods.HttpEntityEnclosingRequestBase;
import java.net.URI;
/**
 * @author xf
 * @version 1.0.0
 * @ClassName HttpGetWithEntity
 * @Description TODO 定义一个带body的GET请求 继承 HttpEntityEnclosingRequestBase
 */
public class HttpGetWithEntity extends HttpEntityEnclosingRequestBase {
    private final static String METHOD_NAME = "GET";

    @Override
    public String getMethod() {
        return METHOD_NAME;
    }
    public HttpGetWithEntity() {
        super();
    }
    public HttpGetWithEntity(final URI uri) {
        super();
        setURI(uri);
    }
    HttpGetWithEntity(final String uri) {
        super();
        setURI(URI.create(uri));
    }

}

HttpGet 请求公共方法/**
  * 发送get请求，参数为json
  * @param url
  * @param param
  * @param encoding
  * @return
  * @throws Exception
  */
public static String sendJsonByGetReq(String url, String param, String encoding) throws Exception {
    String body = "";
    //创建httpclient对象
    CloseableHttpClient client = HttpClients.createDefault();
    HttpGetWithEntity httpGetWithEntity = new HttpGetWithEntity(url);
    HttpEntity httpEntity = new StringEntity(param, ContentType.APPLICATION_JSON);
    httpGetWithEntity.setEntity(httpEntity);
    //执行请求操作，并拿到结果（同步阻塞）
    CloseableHttpResponse response = client.execute(httpGetWithEntity);
    //获取结果实体
    HttpEntity entity = response.getEntity();
    if (entity != null) {
        //按指定编码转换结果实体为String类型
        body = EntityUtils.toString(entity, encoding);
    }
    //释放链接
    response.close();
    return body;
}

react 的 Tag 标签同时存在 onClick 和 onClose 事件时，触发 onClose 的同时也会触发 onClick，如何避免


解决方案这是一个常见的问题。在 React 中，当一个元素同时具有 onClick 和 onClose 事件时，点击关闭按钮会同时触发这两个事件。为了避免这种情况，我们可以使用事件冒泡的阻止机制。以下是解决这个问题的步骤：
在 onClose 处理函数中阻止事件冒泡确保 onClick 事件不会在关闭按钮被点击时触发以下是优化后的代码：
import React from 'react';
import { Tag } from 'antd'; // 假设使用的是 Ant Design 的 Tag 组件

interface TagProps {
  // ... 其他属性
  onClose: () =&gt; void;
  onClick: () =&gt; void;
}

const CustomTag: React.FC&lt;TagProps&gt; = ({ onClose, onClick, ...props }) =&gt; {
  const handleClose = (e: React.MouseEvent&lt;HTMLElement&gt;) =&gt; {
    e.stopPropagation(); // 阻止事件冒泡
    onClose();
  };

  const handleClick = (e: React.MouseEvent&lt;HTMLElement&gt;) =&gt; {
    // 确保点击的不是关闭按钮
    if (!(e.target as HTMLElement).closest('.ant-tag-close-icon')) {
      onClick();
    }
  };

  return (
    &lt;Tag
      {...props}
      onClose={handleClose}
      onClick={handleClick}
    /&gt;
  );
};

// 使用示例
const YourComponent: React.FC = () =&gt; {
  return (
    &lt;CustomTag
      closable
      onClose={() =&gt; console.log('Tag closed')}
      onClick={() =&gt; console.log('Tag clicked')}
    &gt;
      Tag Content
    &lt;/CustomTag&gt;
  );
};

export default YourComponent;

这个解决方案的关键点：

在 onClose 处理函数中使用 e.stopPropagation () 阻止事件冒泡。
在 onClick 处理函数中，我们检查点击的目标是否是关闭图标。如果不是，才触发 onClick 事件。

使用这种方法，当你点击标签的关闭图标时，只会触发 onClose 事件，而不会触发 onClick 事件。点击标签的其他部分时，只会触发 onClick 事件。
注意事项：

这个例子假设使用的是 Ant Design 的 Tag 组件。如果使用其他组件库，可能需要调整 CSS 选择器（例如 .ant-tag-close-icon）。
确保将原来的 Tag 组件替换为这个新的 CustomTag 组件。
这个解决方案适用于大多数情况，但在某些特殊情况下可能需要进一步调整。

如果你的具体实现有所不同，或者使用了不同的组件库，可能需要稍微调整代码。

