&lt;/dependency&gt;



代码封装/**
  * 获得文件编码格式
  *
  * @param file
  * @return
  * @throws IOException
  */
 public static String getFileEncode(File file) throws IOException {
     FileInputStream in = new FileInputStream(file);
     String code = "utf-8";
     byte[] buf = new byte[4096];
     UniversalDetector detector = new UniversalDetector(null);

     // (2)
     int nread;
     while ((nread = in.read(buf)) &gt; 0 &amp;&amp; !detector.isDone()) {
         detector.handleData(buf, 0, nread);
     }
     // (3)
     detector.dataEnd();

     // (4)
     String encoding = detector.getDetectedCharset();
     if (StringUtils.isNotEmpty(encoding)) {
         code = encoding;
     }

     // (5)
     detector.reset();

     return code;
 }

问题描述axios.request({
    url: url,
    method: "post",
    responseType: "blob",
    params: this.queryMap
})

在使用 Axios 进行 HTTP 请求时，如果 params 包含数组类型的变量，默认情况下，Axios 会将数组参数转换成类似 param[]=value1&amp;param[]=value2 的形式。
然而，这种默认行为可能与服务器的预期格式不匹配，导致异常。
如果你希望数组参数以其他格式传递，可以使用 paramsSerializer 来自定义序列化过程。


下面是一个示例，展示如何使用 qs 库将数组参数序列化为所需的格式。
使用 qs 库进行自定义序列化首先，确保你已经安装了 qs 库：

npm install qs




然后，你可以在 Axios 请求中使用 qs.stringify 方法来自定义参数序列化：

import axios from 'axios';

import qs from 'qs';



axios.request({

  url: url,

  method: 'post',

  responseType: 'blob',

  params: this.queryMap,

  paramsSerializer: params =&gt; {

​    return qs.stringify(params, { arrayFormat: 'repeat' });

  }

});




在 qs.stringify 方法中，arrayFormat 有多种选项，你可以根据需要选择适合你的选项：
- 'indices' (默认): param[0]=value0&amp;param[1]=value1
- 'brackets': param[]=value0&amp;param[]=value1
- 'repeat': param=value0&amp;param=value1
- 'comma': param=value0,value1
例如：

paramsSerializer: params =&gt; {

  return qs.stringify(params, { arrayFormat: 'brackets' });

}




另一种方式：手动序列化如果你不想引入额外的库，可以手动实现参数序列化：

function customParamsSerializer(params) {

  const queryString = Object.keys(params).map(key =&gt; {

​    const value = params[key];

​    if (Array.isArray(value)) {

​      return value.map(val =&gt; `${encodeURIComponent(key)}=${encodeURIComponent(val)}`).join('&amp;');

​    } else {

​      return `${encodeURIComponent(key)}=${encodeURIComponent(value)}`;

​    }

  }).join('&amp;');



  return queryString;

}



axios.request({

  url: url,

  method: 'post',

  responseType: 'blob',

  params: this.queryMap,

  paramsSerializer: customParamsSerializer

});




完整示例使用 qs 库
