3. 第三方 API 集成public PaymentResult processPayment(PaymentRequest request) {
    String result = CircuitBreakerUtils.executeWithCircuitBreaker(
        "payment-gateway",
        () -&gt; paymentGateway.charge(request)
    );

    if (result == null) {
        // 支付网关不可用，记录订单并稍后重试
