最佳实践1. 错误处理策略// 前端错误处理
class UserDataCollector {
  async sendData(topic, data, key = null) {
    try {
      return await this.sendViaAPI({topic, message: JSON.stringify(data), key});
    } catch (error) {
      // 静默失败，不影响用户体验
      this.handleError(error, topic, data);
      return null;
    }
  }

  handleError(error, topic, data) {
    // 本地存储失败的数据，后续重试
    const failedData = {
      topic,
      data,
      timestamp: Date.now(),
      error: error.message
    };

    const failures = JSON.parse(localStorage.getItem('failed_data') || '[]');
    failures.push(failedData);
    localStorage.setItem('failed_data', JSON.stringify(failures));

    // 定期重试逻辑
    this.scheduleRetry();
  }
}

2. 性能优化// 批量发送和防抖
class UserDataCollector {
  constructor() {
    this.buffer = [];
    this.batchSize = 10;
    this.flushInterval = 5000; // 5秒

    // 定期刷新缓冲区
    setInterval(() =&gt; this.flush(), this.flushInterval);
  }

  async sendData(topic, data, key = null) {
    // 添加到缓冲区
    this.buffer.push({topic, data, key});

    // 达到批次大小时立即发送
    if (this.buffer.length &gt;= this.batchSize) {
      await this.flush();
    }
  }

  async flush() {
    if (this.buffer.length === 0) return;

    const batch = this.buffer.splice(0);
    try {
      await this.sendBatch(batch);
    } catch (error) {
      // 批次发送失败，重新加入缓冲区
      this.buffer.unshift(...batch);
    }
  }
}

3. 数据脱敏// 敏感数据处理
class UserDataCollector {
  sanitizeData(data) {
    const sanitized = {...data};

    // 移除敏感字段
    delete sanitized.password;
    delete sanitized.token;

    // 脱敏处理
    if (sanitized.email) {
      sanitized.email = this.maskEmail(sanitized.email);
    }

    if (sanitized.phone) {
      sanitized.phone = this.maskPhone(sanitized.phone);
    }

    return sanitized;
  }

  maskEmail(email) {
    const [name, domain] = email.split('@');
    const maskedName = name.charAt(0) + '***' + name.slice(-1);
    return `${maskedName}@${domain}`;
  }
}

